from src.workflow import Store, Archive, Workspace, Preview

class Timers:
    def __init__(self): self.jobs=[]; self.next=0
    def schedule(self, callback, delay):
        self.next += 1; handle=self.next; self.jobs.append([handle, callback, delay, False]); return handle
    def cancel(self, handle):
        for job in self.jobs:
            if job[0] == handle: job[3] = True
    def run(self):
        jobs, self.jobs = self.jobs, []
        for _, callback, _, cancelled in jobs:
            if not cancelled: callback()

class Env(Timers):
    def __init__(self):
        super().__init__(); self.store=Store({'a':'old','b':'bee'}); self.archive=Archive(); self.out=[]; self.writes=[]
    def write(self, key, text): self.writes.append((key,text)); return self.store.write(key,text)
    def capture(self, snapshot): return self.archive.capture(snapshot)
    def output(self, kind, value): self.out.append((kind,value))

e=Env(); w=Workspace(e)
w.open('a'); w.edit('1'); w.edit('12'); w.edit('123')
assert e.writes == []
e.run(); assert e.writes == [('a','123')] and e.store.read('a') == '123'
