w.edit('closing'); w.close(); assert e.store.read('a') == 'closing'
w.open('a'); assert w.current.text == 'closing'
w.edit('submitted'); receipt=w.submit(); assert receipt == {'id':'a','text':'submitted'} and e.store.read('a') == 'submitted'
w.edit('after-submit'); e.run(); assert e.store.read('a') == 'after-submit' and e.archive.list()[-1] == {'id':'a','text':'submitted'}
