e2=Env(); w2=Workspace(e2); w2.open('a'); w2.edit('depart')
original=e2.write
def replace(key,text):
    result=original(key,text)
    if key == 'a': w2.open('b')
    return result
e2.write=replace
w2.close(); assert e2.store.read('a') == 'depart' and w2.current is not None and w2.current.id == 'b'
print('workflow validation passed')
